# Compute log of a vector (with 0 -> -Inf handling)
log_safe <- function(x) {
  if (is.numeric(x)) {
    log(x + 0.0000001)  # Small epsilon to avoid log(0)
  } else {
    log(x)
  }
}

# Compute log of a function applied to x
log_density <- function(density_func, x) {
  if (is.function(density_func)) {
    d <- density_func(x)
