# Check if a function is log-concave using second derivative approximation
check_log_concavity <- function(density_func, domain, n = 100) {
  if (!validate_domain(domain)) {
    return(list(log_concave = FALSE, message = "Invalid domain"))
  }

  log_dens <- log_density(density_func, domain)

  # Compute second derivative using finite differences
  h <- (domain[2] - domain[1]) / n
  d2 <- (log_dens[-1] - 2 * log_dens[-c(1, length(log_dens))]) / (h * h)

  # Check if second derivative is non-positive (concave)
  # Allow some tolerance for numerical errors
  if (all(d2 <= 0.001)) {
    return(list(log_concave = TRUE, message = "Distribution is log-concave"))
  } else {
    return(list(log_concave = FALSE, message = "Distribution is NOT log-concave (convex regions detected)"))
  }
}

