ars <- function(density_function, domain, n = 100) {
  """
  Adaptive Rejection Sampling (Gilks & Wild, 1992)

  Arguments:
    density_function: Function that computes the density (possibly unnormalized)
                      at a point or vector of points
    domain: Numeric vector of length 2 specifying the sampling domain [a, b]
    n: Number of samples to generate (default: 100)

  Returns:
    Numeric vector of n samples from the distribution

  Errors:
    Throws error if inputs are invalid or distribution is not log-concave
  """

  # Validate inputs
  if (!validate_n(n)) {
    stop("Error: 'n' must be a positive numeric value")
  }

  if (!validate_density_function(density_function)) {
    stop("Error: 'density_function' must be a valid function")
  }

  domain <- validate_domain(domain)
  if (is.null(domain)) {
    stop("Error: 'domain' must be a numeric vector of length 2")
  }

  if (!validate_domain(domain)) {
    stop("Error: 'domain' must be a numeric vector of length 2")
  }

  if (domain[1] >= domain[2]) {
    stop("Error: domain[1] must be less than domain[2]")
  }

  if (density_function(domain[1]) == 0 || density_function(domain[2]) == 0) {
    stop("Error: density must be positive at domain boundaries")
  }

  # Check log-concavity
  concavity_check <- check_log_concavity(density_function, domain)
  if (!concavity_check$log_concave) {
    stop(paste("Error:", concavity_check$message))
  }

  # Initial envelope construction
  envelope <- compute_upper_envelope(density_function, domain, anchor = domain[1])

  # Generate samples
  samples <- numeric(n)

  for (i in 1:n) {
    # Sample from the upper envelope
    # Sample x from the piecewise linear envelope
    # For each segment, sample proportional to the segment length

    # Get segment parameters
    n_segments <- length(envelope) - 1
    segment_lengths <- envelope[, 2] - envelope[1, 2]

    # Sample which segment
    segment_idx <- sample(1:n_segments, 1)

    # Get segment coordinates
    x1 <- envelope[segment_idx, 1]
    y1 <- envelope[segment_idx, 2]
    x2 <- envelope[segment_idx + 1, 1]
    y2 <- envelope[segment_idx + 1, 2]

    # Sample x from the linear segment
    if (x1 == x2) {
      # Degenerate case
      samples[i] <- x1
    } else {
      # Sample from exponential distribution on the segment
      # P(X < x) = (exp(y1) - exp(y)) / (exp(y1) - exp(y2))
      u <- runif(1)
      if (u < 0.5) {
        samples[i] <- x1 + (x2 - x1) * (1 - exp(-u * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      } else {
        samples[i] <- x2 + (x1 - x2) * (1 - exp(-(u - 0.5) * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      }
    }

    # Compute log-density at sample point
    log_d <- log_density(density_function, samples[i])

    # Compute envelope value at sample point
    # Find which segment contains the sample
    envelope_check <- envelope
    for (j in 1:(n_segments - 1)) {
      if (samples[i] >= envelope_check[j, 1] && samples[i] <= envelope_check[j + 1, 1]) {
        # Interpolate envelope value
        x1_e <- envelope_check[j, 1]
        x2_e <- envelope_check[j + 1, 1]
        y1_e <- envelope_check[j, 2]
        y2_e <- envelope_check[j + 1, 2]

        if (x1_e == x2_e) {
          y_envelope <- y1_e
        } else {
          # Linear interpolation
          t <- (samples[i] - x1_e) / (x2_e - x1_e)
          y_envelope <- y1_e + t * (y2_e - y1_e)
        }
        break
      }
    }

    # Accept/reject
    if (log_d + rnorm(1) > y_envelope) {
      samples[i] <- samples[i]
    } else {
      # Regenerate
      i <- i - 1
    }
  }

  return(samples)
}

# ============================================================================
# STATISTICS FUNCTIONS
# ============================================================================

compute_statistics <- function(samples) {
  list(
    mean = mean(samples),
    sd = sd(samples),
    min = min(samples),
    max = max(samples),
    n = length(samples)
  )
}

