  concavity_check <- check_log_concavity(density_function, domain)
  if (!concavity_check$log_concave) {
    stop(paste("Error:", concavity_check$message))
  }

  # Initial envelope construction
  envelope <- compute_upper_envelope(density_function, domain, anchor = domain[1])

  # Generate samples
  samples <- numeric(n)

  for (i in 1:n) {
    n_segments <- length(envelope) - 1
    segment_lengths <- envelope[, 2] - envelope[1, 2]

    segment_idx <- sample(1:n_segments, 1)

    x1 <- envelope[segment_idx, 1]
    y1 <- envelope[segment_idx, 2]
    x2 <- envelope[segment_idx + 1, 1]
    y2 <- envelope[segment_idx + 1, 2]

    if (x1 == x2) {
      samples[i] <- x1
    } else {
      u <- runif(1)
      if (u < 0.5) {
        samples[i] <- x1 + (x2 - x1) * (1 - exp(-u * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      } else {
        samples[i] <- x2 + (x1 - x2) * (1 - exp(-(u - 0.5) * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      }
    }

    log_d <- log_density(density_function, samples[i])

    envelope_check <- envelope
    for (j in 1:(n_segments - 1)) {
      if (samples[i] >= envelope_check[j, 1] && samples[i] <= envelope_check[j + 1, 1]) {
        x1_e <- envelope_check[j, 1]
        x2_e <- envelope_check[j + 1, 1]
        y1_e <- envelope_check[j, 2]
        y2_e <- envelope_check[j + 1, 2]

        if (x1_e == x2_e) {
          y_envelope <- y1_e
        } else {
          t <- (samples[i] - x1_e) / (x2_e - x1_e)
          y_envelope <- y1_e + t * (y2_e - y1_e)
        }
        break
      }
    }

    if (log_d + rnorm(1) > y_envelope) {
      samples[i] <- samples[i]
    } else {
      i <- i - 1
    }
  }

  return(samples)
}

