check_log_concavity <- function(density_func, domain, n = 100) {
  if (!validate_domain(domain)) {
    return(list(log_concave = FALSE, message = "Invalid domain"))
  }

  log_dens <- log_density(density_func, domain)

  h <- (domain[2] - domain[1]) / n
  d2 <- (log_dens[-1] - 2 * log_dens[-c(1, length(log_dens))]) / (h * h)

  if (all(d2 <= 0.001)) {
    return(list(log_concave = TRUE, message = "Distribution is log-concave"))
  } else {
    return(list(log_concave = FALSE, message = "Distribution is NOT log-concave (convex regions detected)"))
  }
}

# ============================================================================
# UPPER ENVELOPE CONSTRUCTION
# ============================================================================

compute_upper_envelope <- function(density_func, domain, anchor = NULL) {
  if (!validate_domain(domain)) {
    stop("Invalid domain specified")
  }

  log_dens_left <- log_density(density_func, domain[1])
  log_dens_right <- log_density(density_func, domain[2])

  if (is.null(anchor)) {
    tryCatch({
      anchor <- optimize(density_func, interval = domain, maximum)$maximum
      log_dens_anchor <- log_density(density_func, anchor)
    }, error = function(e) {
      anchor <- mean(domain)
      log_dens_anchor <- log_density(density_func, anchor)
    })
  } else {
    log_dens_anchor <- log_density(density_func, anchor)
  }

  envelope <- list()
  envelope[[1]] <- c(domain[1], log_dens_left)
  envelope[[2]] <- c(anchor, log_dens_anchor)
  envelope[[3]] <- c(domain[2], log_dens_right)

  idx <- order(envelope[, 1])
  envelope <- envelope[idx, ]

  return(envelope)
}

