  if (is.numeric(n) && length(n) == 1 && n > 0) return(TRUE) else FALSE
}

validate_domain <- function(domain) {
  if (is.null(domain) || length(domain) == 0) return(NULL)
  if (!is.numeric(domain)) return(FALSE)
  if (length(domain) != 2) return(FALSE)
  if (domain[1] >= domain[2]) return(FALSE)
  return(TRUE)
}

validate_density_function <- function(density_func) {
  if (!is.function(density_func)) return(FALSE)
  tryCatch({
    result <- density_func(c(0.1, 1, 2))
    if (is.numeric(result) && length(result) == 3) return(TRUE)
  }, error = function(e) return(FALSE))
  FALSE
}

check_log_concavity <- function(density_func, domain, n = 100) {
  if (!validate_domain(domain)) return(list(log_concave = FALSE, message = "Invalid domain"))
  log_dens <- log_density(density_func, domain)
  h <- (domain[2] - domain[1]) / n
  d2 <- (log_dens[-1] - 2 * log_dens[-c(1, length(log_dens))]) / (h * h)
  if (all(d2 <= 0.001)) return(list(log_concave = TRUE, message = "Distribution is log-concave"))
  return(list(log_concave = FALSE, message = "Distribution is NOT log-concave"))
}

compute_upper_envelope <- function(density_func, domain, anchor = NULL) {
  if (!validate_domain(domain)) stop("Invalid domain specified")
  log_dens_left <- log_density(density_func, domain[1])
  log_dens_right <- log_density(density_func, domain[2])
  if (is.null(anchor)) {
    tryCatch({
      anchor <- optimize(density_func, interval = domain, maximum)$maximum
      log_dens_anchor <- log_density(density_func, anchor)
    }, error = function(e) {
      anchor <- mean(domain)
      log_dens_anchor <- log_density(density_func, anchor)
    })
  } else {
    log_dens_anchor <- log_density(density_func, anchor)
  }
  envelope <- data.frame(x = c(domain[1], anchor, domain[2]), 
                         y = c(log_dens_left, log_dens_anchor, log_dens_right))
  envelope <- envelope[order(envelope$x), ]
  return(envelope)
}

ars <- function(density_function, domain, n = 100) {
  if (!validate_n(n)) stop("Error: 'n' must be a positive numeric value")
  if (!validate_density_function(density_function)) stop("Error: 'density_function' must be a valid function")

  domain_valid <- validate_domain(domain)
  if (is.null(domain_valid)) stop("Error: 'domain' must be a numeric vector of length 2")
  if (!domain_valid) stop("Error: 'domain' must be a numeric vector of length 2 with domain[1] < domain[2]")

  if (density_function(domain[1]) == 0 || density_function(domain[2]) == 0) {
    stop("Error: density must be positive at domain boundaries")
  }

  concavity_check <- check_log_concavity(density_function, domain)
  if (!concavity_check$log_concave) stop(paste("Error:", concavity_check$message))

  envelope <- compute_upper_envelope(density_function, domain, anchor = domain[1])
  samples <- numeric(n)

  for (i in 1:n) {
    n_segments <- nrow(envelope) - 1
    segment_idx <- sample(1:n_segments, 1)

    x1 <- envelope$x[segment_idx]
    y1 <- envelope$y[segment_idx]
    x2 <- envelope$x[segment_idx + 1]
    y2 <- envelope$y[segment_idx + 1]

    if (x1 == x2) {
      samples[i] <- x1
    } else {
      u <- runif(1)
      if (u < 0.5) {
        samples[i] <- x1 + (x2 - x1) * (1 - exp(-u * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      } else {
        samples[i] <- x2 + (x1 - x2) * (1 - exp(-(u - 0.5) * (y2 - y1))) / (1 - exp(-(y2 - y1)))
      }
    }

    log_d <- log_density(density_function, samples[i])

    # Find envelope value at sample point
    y_envelope <- NA
    for (j in 1:(n_segments)) {
      seg_j <- j + 1
      if (seg_j > n_segments) seg_j <- n_segments
      if (samples[i] >= envelope$x[j] && samples[i] <= envelope$x[seg_j]) {
        if (envelope$x[j] == envelope$x[seg_j]) {
          y_envelope <- envelope$y[j]
        } else {
          t <- (samples[i] - envelope$x[j]) / (envelope$x[seg_j] - envelope$x[j])
          y_envelope <- envelope$y[j] + t * (envelope$y[seg_j] - envelope$y[j])
        }
        break
      }
    }

    if (is.na(y_envelope)) {
      if (envelope$x[n_segments] == envelope$x[n_segments + 1]) {
        y_envelope <- envelope$y[n_segments]
      } else {
        t <- (samples[i] - envelope$x[n_segments]) / (envelope$x[n_segments + 1] - envelope$x[n_segments])
        y_envelope <- envelope$y[n_segments] + t * (envelope$y[n_segments + 1] - envelope$y[n_segments])
      }
    }

    if (log_d + rnorm(1) > y_envelope) {
      samples[i] <- samples[i]
    } else {
      i <- i - 1
    }
  }

  return(samples)
}

